//! GitHub WASI integration plugin implementing `darkfactory:integrations/forge@0.1.0`.
//!
//! [`GitHub`] is generic over a [`Transport`] and a [`Clock`] so it can be unit-tested natively;
//! the component wires them to `wasi:http` and `wasi:clocks`. Credentials are never handled here:
//! the host injects `Authorization` into every outgoing request. Webhook signatures are checked by
//! the host as well, through `webhook-signature.verify` ([`webhook`]).

#![expect(clippy::same_length_and_capacity, reason = "generated by wit-bindgen")]

wit_bindgen::generate!({
    path: "../../contract/wit/integrations",
    world: "forge",
    generate_all,
});

mod api;
mod draft;
mod error;
#[cfg(test)]
mod operations;
mod settings;
mod timestamp;
mod wasi_transport;
mod webhook;

use darkfactory::integrations::types::{Error, IssueRef, PullRequestRef, RepoRef};
use darkfactory::integrations::webhook_signature;
use exports::darkfactory::integrations::issues::{Comment, Guest as IssuesGuest, Issue};
use exports::darkfactory::integrations::pull_requests::{
    AuthorRole, Feedback, Guest as PullRequestsGuest, NewPullRequest, PostedComment, PullRequest,
    PullRequestUpdate,
};
use exports::darkfactory::integrations::webhooks::{Guest as WebhooksGuest, ParsedEvent};
use wasi_transport::{StderrLog, WallClock, WasiTransport};

pub use api::{Clock, GitHub, Log, Method, Request, Response, Transport};
pub use settings::{DraftMode, Settings};

pub struct GitHubPlugin;

impl PullRequestsGuest for GitHubPlugin {
    fn create(request: NewPullRequest) -> Result<PullRequest, Error> {
        instance()?.create(&request)
    }

    fn find_open(repo: RepoRef, head: String, base: String) -> Result<Option<PullRequest>, Error> {
        instance()?.find_open(&repo, &head, &base)
    }

    fn get(id: PullRequestRef) -> Result<PullRequest, Error> {
        instance()?.get(&id)
    }

    fn update(id: PullRequestRef, changes: PullRequestUpdate) -> Result<PullRequest, Error> {
        instance()?.update(&id, &changes)
    }

    fn list_feedback(id: PullRequestRef, since: Option<String>) -> Result<Feedback, Error> {
        instance()?.list_feedback(&id, since.as_deref())
    }

    fn reply(id: PullRequestRef, thread: String, body: String) -> Result<PostedComment, Error> {
        instance()?.reply(&id, &thread, &body)
    }
}

impl IssuesGuest for GitHubPlugin {
    fn get(id: IssueRef) -> Result<Issue, Error> {
        instance()?.get_issue(&id)
    }

    fn add_comment(id: IssueRef, body: String) -> Result<Comment, Error> {
        instance()?.add_comment(&id, &body)
    }
}

impl WebhooksGuest for GitHubPlugin {
    fn handle_webhook(
        headers: Vec<(String, String)>,
        body: Vec<u8>,
    ) -> Result<Vec<ParsedEvent>, Error> {
        let signature = webhook::signature(&headers).ok_or_else(|| {
            Error::Unauthorized("missing or malformed `X-Hub-Signature-256`".to_string())
        })?;
        if !webhook_signature::verify(&signature) {
            return Err(Error::Unauthorized(
                "`X-Hub-Signature-256` does not match".to_string(),
            ));
        }
        webhook::parse(&headers, &body)
    }

    fn whoami() -> Result<String, Error> {
        instance()?.whoami()
    }

    fn author_role(repo: RepoRef, login: String) -> Result<AuthorRole, Error> {
        instance()?.author_role(&repo, &login)
    }
}

/// Reads the settings through `wasi:config/store` and talks to GitHub over `wasi:http`.
fn instance() -> Result<GitHub<WasiTransport, WallClock, StderrLog>, Error> {
    Ok(GitHub::new(
        WasiTransport,
        WallClock,
        StderrLog,
        Settings::read(config)?,
    ))
}

fn config(key: &str) -> Result<Option<String>, Error> {
    wasi::config::store::get(key).map_err(|e| Error::Config(format!("reading `{key}`: {e:?}")))
}

#[cfg(target_arch = "wasm32")]
export!(GitHubPlugin);
